  VerifyOtpResponse,
  RefreshTokenRequest,
  RefreshTokenResponse,
} from '../types/auth.types';

const extractErrorMessage = (error: unknown, fallback: string): string => {
  if (
    error instanceof AxiosError &&
    error.response?.data &&
    typeof error.response.data === 'object' &&
    'message' in error.response.data
  ) {
    return String(error.response.data.message);
  }
  return fallback;
};

export const authApi = {
  login: async (credentials: LoginCredentials): Promise<AuthResponse> => {
    try {
      const res = await apiClient.post<AuthResponse>('/api/auth/login', credentials);
      return res.data;
    } catch (error: unknown) {
      throw new Error(extractErrorMessage(error, 'Login failed'), {
        cause: error,
      });
    }
  },

  sendRegisterOtp: async (
    payload: SendRegisterOtpRequest,
  ): Promise<SendRegisterOtpResponse> => {
    try {
      const res = await apiClient.post<SendRegisterOtpResponse>(
        '/api/auth/send-register-otp',
        payload,
      );
      return res.data;
    } catch (error: unknown) {
      throw new Error(
        extractErrorMessage(error, 'Failed to send verification code'),
        { cause: error },
      );
    }
  },

  verifyOtp: async (
    payload: VerifyOtpRequest,
  ): Promise<VerifyOtpResponse> => {
    try {
      const res = await apiClient.post<VerifyOtpResponse>(
        '/api/auth/verify-otp',
        payload,
      );
      return res.data;
    } catch (error: unknown) {
      throw new Error(
        extractErrorMessage(error, 'Invalid or expired verification code'),
        { cause: error },
      );
    }
  },

  register: async (data: RegisterData): Promise<AuthResponse> => {
    try {
      const res = await apiClient.post<AuthResponse>('/api/auth/register', data);
      return res.data;
    } catch (error: unknown) {
      throw new Error(extractErrorMessage(error, 'Registration failed'), {
        cause: error,
      });
    }
  },

  refreshToken: <REDACTED> (
