      return res.data;
    } catch (error: unknown) {
      throw new Error(extractErrorMessage(error, 'Failed to refresh token'), {
        cause: error,
      });
    }
  },

  getMe: async (): Promise<{ success: boolean; data: User }> => {
    try {
