import { useMutation, useQueryClient } from '@tanstack/react-query';
import { workflowService } from '../services/workflow.service';
import { workflowKeys } from './useWorkflows';
import { versionKeys } from './useWorkflowVersions';
import { triggerKeys } from './useWorkflowTriggers';
import { draftKeys } from './useWorkflowDraft';
import type { WorkflowTemplate } from '../templates/catalog';
import type { PublishResult } from '../types/workflow.types';

export function useCreateWorkflowMutation() {
  const queryClient = useQueryClient();
  return useMutation({
    mutationFn: (name?: string) => workflowService.createWorkflow(name),
    onSuccess: () => {
      void queryClient.invalidateQueries({ queryKey: workflowKeys.all });
    },
  });
}

export function useCreateWorkflowFromTemplateMutation() {
  const queryClient = useQueryClient();
  return useMutation({
    mutationFn: async (template: WorkflowTemplate) => {
      const workflowId = await workflowService.createWorkflow(template.title);
      await workflowService.saveDraft(workflowId, {
        nodes: structuredClone(template.nodes),
        edges: structuredClone(template.edges),
        viewport: { x: 0, y: 0, zoom: 1 },
      });
      return workflowId;
    },
    onSuccess: () => {
      void queryClient.invalidateQueries({ queryKey: workflowKeys.all });
    },
  });
}

export function useRenameWorkflowMutation() {
  const queryClient = useQueryClient();
  return useMutation({
    mutationFn: ({ id, name }: { id: string; name: string }) =>
      workflowService.renameWorkflow(id, name),
    onSuccess: (_, { id }) => {
      void queryClient.invalidateQueries({ queryKey: workflowKeys.all });
      void queryClient.invalidateQueries({ queryKey: draftKeys.detail(id) });
    },
  });
}

export function useDeleteWorkflowMutation() {
  const queryClient = useQueryClient();
  return useMutation({
    mutationFn: (id: string) => workflowService.deleteWorkflow(id),
    onSuccess: () => {
      void queryClient.invalidateQueries({ queryKey: workflowKeys.all });
    },
  });
}

export function useSaveDraftMutation() {
  const queryClient = useQueryClient();
  return useMutation({
    mutationFn: ({ id, definition }: { id: string; definition: unknown }) =>
      workflowService.saveDraft(id, definition),
    onSuccess: (_, { id }) => {
      void queryClient.invalidateQueries({ queryKey: draftKeys.detail(id) });
      void queryClient.invalidateQueries({ queryKey: versionKeys.draftStatus(id) });
    },
  });
}

export function usePublishWorkflowMutation() {
  const queryClient = useQueryClient();
  return useMutation<PublishResult, unknown, string>({
    mutationFn: (id: string) => workflowService.publishWorkflow(id),
    onSuccess: (_, id) => {
      void queryClient.invalidateQueries({ queryKey: workflowKeys.all });
      void queryClient.invalidateQueries({ queryKey: draftKeys.detail(id) });
      void queryClient.invalidateQueries({ queryKey: versionKeys.all });
      void queryClient.invalidateQueries({ queryKey: triggerKeys.activation(id) });
    },
  });
}

export function useWorkflowMutations() {
  const createWorkflowMutation = useCreateWorkflowMutation();
  const createFromTemplateMutation = useCreateWorkflowFromTemplateMutation();
  const renameWorkflowMutation = useRenameWorkflowMutation();
  const deleteWorkflowMutation = useDeleteWorkflowMutation();
  const saveDraftMutation = useSaveDraftMutation();
  const publishWorkflowMutation = usePublishWorkflowMutation();

  return {
    createWorkflowMutation,
    createFromTemplateMutation,
    renameWorkflowMutation,
    deleteWorkflowMutation,
    saveDraftMutation,
    publishWorkflowMutation,
  };
}

import { AxiosError } from 'axios';
import { workflowApi } from '../api/workflow.api';
import type { NodeTypeDefinition } from '../models/workflow.model';
import type { PublishResult } from '../types/workflow.types';
import {
  WorkflowPublishValidationError,
  type WorkflowValidationIssue,
} from '../models/workflow-validation.model';

function isValidationIssue(value: unknown): value is WorkflowValidationIssue {
  if (typeof value !== 'object' || value === null) return false;
  const issue = value as Record<string, unknown>;
  return (
    typeof issue.code === 'string' &&
    typeof issue.message === 'string' &&
    (issue.nodeId === undefined || typeof issue.nodeId === 'string') &&
    (issue.field === undefined || typeof issue.field === 'string')
  );
}

export const workflowService = {
  async createWorkflow(name?: string): Promise<string> {
    try {
      const data = await workflowApi.createWorkflow(name);
      return data.id;
    } catch (error: unknown) {
      throw new Error('Failed to create workflow', { cause: error });
    }
  },

  async getWorkflows(): Promise<import('../types/workflow.types').WorkflowSummary[]> {
    try {
      return await workflowApi.getWorkflows();
    } catch (error: unknown) {
      throw new Error('Failed to get workflows', { cause: error });
    }
  },

  async renameWorkflow(id: string, name: string): Promise<void> {
    try {
      await workflowApi.renameWorkflow(id, name);
    } catch (error: unknown) {
      throw new Error('Failed to rename workflow', { cause: error });
    }
  },

  async deleteWorkflow(id: string): Promise<void> {
    try {
      await workflowApi.deleteWorkflow(id);
    } catch (error: unknown) {
      throw new Error('Failed to delete workflow', { cause: error });
    }
  },

  async getDraft(id: string): Promise<unknown> {
    try {
      return await workflowApi.getDraft(id);
    } catch (error: unknown) {
      if (error instanceof AxiosError && error.response?.status === 404) {
        return {
          definition: {
            nodes: [],
            edges: [],
            viewport: { x: 0, y: 0, zoom: 1 },
          },
        };
      }
      throw new Error('Failed to get draft', { cause: error });
    }
  },

  async saveDraft(id: string, definition: unknown): Promise<void> {
    try {
      await workflowApi.saveDraft(id, definition);
    } catch (error: unknown) {
      throw new Error('Failed to save draft', { cause: error });
    }
  },

  async publishWorkflow(id: string): Promise<PublishResult> {
    try {
      return await workflowApi.publishWorkflow(id);
    } catch (error: unknown) {
      if (
        error instanceof AxiosError &&
        error.response?.data &&
        typeof error.response.data === 'object' &&
        'message' in error.response.data
      ) {
        const response = error.response.data as Record<string, unknown>;
        const issues = Array.isArray(response.issues)
          ? response.issues.filter(isValidationIssue)
          : [];
        if (issues.length > 0) {
          throw new WorkflowPublishValidationError(
            String(response.message),
            issues,
            { cause: error },
          );
        }
        throw new Error(String(response.message), { cause: error });
      }
      throw new Error('Failed to publish workflow', { cause: error });
    }
  },

  async getNodeTypes(): Promise<NodeTypeDefinition[]> {
    try {
      return await workflowApi.getNodeTypes();
    } catch (error: unknown) {
      console.warn('Failed to get node types, returning empty array fallback:', error);
      return [];
    }
  },
};
