import type { Node, Edge } from '@xyflow/react';

interface HomePageProps {
  onCreateWorkflow: (templateName?: string, initialDefinition?: { nodes: Node[]; edges: Edge[] }) => void;
  loading?: boolean;
}

export const HomePage: React.FC<HomePageProps> = ({
  onCreateWorkflow,
  loading,
}) => {
  const [isAuthModalOpen, setIsAuthModalOpen] = useState(false);
  const [authModalTab, setAuthModalTab] = useState<'login' | 'register'>('login');
  const isAuthenticated = useAuthStore((state) => state.isAuthenticated);

  const openAuthModal = (tab: 'login' | 'register' = 'login') => {
    setAuthModalTab(tab);
    setIsAuthModalOpen(true);
  };

  const handleCreateWorkflow = (templateName?: string, initialDefinition?: { nodes: Node[]; edges: Edge[] }) => {
    if (!isAuthenticated) {
      openAuthModal('login');
      return;
    }
    onCreateWorkflow(templateName, initialDefinition);
  };

  return (
    <div className="min-h-screen bg-background text-foreground flex flex-col">
      {/* 1. Navbar */}
      <Navbar
        onCreateWorkflow={() => handleCreateWorkflow()}
        onOpenAuthModal={openAuthModal}
        loading={loading}
      />

